typescript:
# Instance of ci/_contract.md
typescript:
  runs-on: ubuntu-latest
  steps:
    - uses: actions/checkout@v4
    - uses: actions/setup-node@v4
      with:
        node-version: 20
        cache: npm
    - name: install
      run: npm ci
    - name: verify configured checks
      run: |
        node -e '
        const { spawnSync } = require("node:child_process");
        const scripts = require("./package.json").scripts ?? {};
        for (const name of ["format:check", "lint", "typecheck", "test", "build"]) {
          const configured = Object.hasOwn(scripts, name);
          if (!configured && name !== "test") {
            console.log(`${name}: not applicable (no npm script; runner omitted)`);
            continue;
          }
          if (!configured || typeof scripts[name] !== "string" || !scripts[name].trim()) {
            console.error(`${name}: unavailable (${name === "test" ? "required" : "configured"} npm script missing or invalid). ${name === "test" ? "Define a real runner: npm pkg set scripts.test=\"node --test\" && npm test; then rerun CI." : "Fix the script in package.json and rerun CI."}`);
            process.exitCode = 1;
            continue;
          }
          const runner = `npm run ${name}`;
          const result = spawnSync("npm", ["run", name], { stdio: "inherit" });
          const exit = result.status ?? "unavailable";
          console.log(`${name}: runner=${runner} exit=${exit} result=${exit === 0 ? "passed" : "failed"}`);
          if (exit !== 0) process.exitCode = 1;
        }
        '
